COPY public.tipo_evento (id_tipo_evento, id_usuario_registra, nombre_tipo_evento, descripcion_tipo_evento, estado_tipo_evento) FROM stdin;
1	1	Congresos	Encuentros académicos de investigación e innovación	t
2	1	Conferencias	Charlas magistrales con expertos nacionales e internacionales	t
3	1	Talleres	Sesiones prácticas de aprendizaje técnico y herramientas	t
