    apellidos_usuario character varying(60) NOT NULL,
    correo_electronico character varying(120) NOT NULL,
    telefono_usuario character varying(20),
    fecha_nacimiento date,
    fecha_registro timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    estado_usuario character varying(12) DEFAULT 'activo'::character varying NOT NULL,
    programa_academico character varying(80),
    perfil_extendido jsonb,
    CONSTRAINT ck_usuario_estado CHECK (((estado_usuario)::text = ANY ((ARRAY['activo'::character varying, 'inactivo'::character varying, 'suspendido'::character varying])::text[])))
);


ALTER TABLE public.usuario OWNER TO postgres;

