--
-- TOC entry 261 (class 1259 OID 41470)
-- Name: vw_reporte_ventas_consolidadas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_reporte_ventas_consolidadas AS
 SELECT p.nombre_producto AS titulo_producto,
    tp.nombre_tipo_producto AS categoria_producto,
    (((u.nombres_usuario)::text || ' '::text) || (u.apellidos_usuario)::text) AS nombre_comprador,
    tu.nombre_tipo_usuario AS descripcion_tipo_usuario,
    sum(cp.valor_total) AS total_pagado
   FROM ((((public.compra_producto cp
     JOIN public.producto p ON ((cp.id_producto = p.id_producto)))
     JOIN public.tipo_producto tp ON ((p.id_tipo_producto = tp.id_tipo_producto)))
     JOIN public.usuario u ON ((cp.id_usuario_comprador = u.id_usuario)))
     JOIN public.tipo_usuario tu ON ((u.id_tipo_usuario = tu.id_tipo_usuario)))
  WHERE ((tu.nombre_tipo_usuario)::text = ANY ((ARRAY['Egresado'::character varying, 'Estudiante'::character varying])::text[]))
  GROUP BY p.nombre_producto, tp.nombre_tipo_producto, u.nombres_usuario, u.apellidos_usuario, tu.nombre_tipo_usuario
 HAVING (sum(cp.valor_total) > (100000)::numeric);


ALTER VIEW public.vw_reporte_ventas_consolidadas OWNER TO postgres;

